          rgba(255, 255, 255, .14) 18%,
          transparent 48%); opacity: 0.9; transition: transform 0.12s linear; z-index: -1;}
.liquid-btn:hover{transform: translateY(-5px) scale(1.01); border-color: rgba(255, 255, 255, 0.25);}
.fade-edge{mask-image: linear-gradient(to right, transparent, black 10%, black 90%, transparent);}
.scroll-fade{mask-image: linear-gradient(transparent, black 12%, black 88%, transparent);}
